const DG_DATA = [{"id": "marsvin-er-diagram", "group": "Structure", "title": "ER diagram", "desc": "The 15 database tables and how they relate.", "src": "erDiagram\n    PRODUCTS ||--o| ANIMALS : \"extends (TPT)\"\n    PRODUCTS ||--o| STOCKPRODUCTS : \"extends (TPT)\"\n    ANIMALS ||--o| ANIMALS : \"BondedWithId (no FK)\"\n\n    USERS ||--o{ PENDINGLOGINS : \"FK\"\n    USERS ||--o{ CARTITEMS : \"FK\"\n    USERS ||--o{ ORDERS : \"FK, nullable\"\n    USERS ||--o{ SHIFTS : \"FK\"\n    USERS ||--o{ TIMEOFFREQUESTS : \"FK\"\n\n    ORDERS ||--|{ ORDERITEMS : \"FK\"\n\n    PRODUCTS ||..o{ CARTITEMS : \"ProductId, no FK\"\n    PRODUCTS ||..o{ ORDERITEMS : \"snapshot, no FK\"\n    PRODUCTS ||..o{ PROMOTIONS : \"ProductId, no FK\"\n    USERS ||..o{ AUDITLOG : \"ActorUserId, no FK\"\n    ORDERS ||..o{ CONTACTMESSAGES : \"OrderId as typed, no FK\"\n\n    PRODUCTS {\n        int ProductId PK \"not IDENTITY - assigned in code\"\n        tinyint ProductType \"1 Animal, 2 StockProduct\"\n        nvarchar200 Name\n        nvarchar200 NameEn \"nullable\"\n        nvarchar500 Description\n        nvarchar500 DescriptionEn \"nullable\"\n        decimal Price \"decimal(10,2)\"\n    }\n\n    ANIMALS {\n        int ProductId PK \"also FK to Products\"\n        nvarchar100 Breed\n        nvarchar100 BreedEn \"nullable\"\n        tinyint Sex \"0 Boar, 1 Sow\"\n        date DateOfBirth\n        nvarchar100 Colour\n        nvarchar100 ColourEn \"nullable\"\n        char7 CoatPrimary \"hex, drives the SVG\"\n        char7 CoatSecondary \"hex\"\n        tinyint Status \"0 Available 1 Reserved 2 Sold 3 NotForSale\"\n        int BondedWithId \"nullable, self-ref, no FK\"\n        nvarchar500 Personality\n        nvarchar500 PersonalityEn \"nullable\"\n        nvarchar300 PhotoUrl \"nullable, must be under /img\"\n    }\n\n    STOCKPRODUCTS {\n        int ProductId PK \"also FK to Products\"\n        nvarchar50 Sku UK\n        tinyint Category \"0 Hay 1 Food 2 Cage 3 House 4 Toy 5 Bedding 6 Care\"\n        int StockQuantity \"CHECK >= 0\"\n        nvarchar20 Unit \"nullable\"\n        nvarchar300 PhotoUrl \"nullable, must be under /img\"\n        int WeightGrams \"default 500, what shipping is priced from\"\n        nvarchar100 Brand \"nullable\"\n    }\n\n    USERS {\n        int UserId PK\n        nvarchar256 Email UK\n        nvarchar500 PasswordHash \"PBKDF2 via PasswordHasher\"\n        nvarchar200 DisplayName\n        tinyint Role \"0 Customer, 1 Employee, 2 Admin\"\n        bit IsActive\n        datetime2 CreatedAt\n        datetime2 LastActiveAt \"drives 2-year auto-deletion\"\n        tinyint InactivityWarningStage \"0 none, 1 two months, 2 one month\"\n        nvarchar500 TotpSecret \"nullable, encrypted with IDataProtector\"\n        bit TotpEnabled \"true only after a code was confirmed\"\n        uniqueidentifier SecurityStamp \"replaced on password change, ends old sessions\"\n        bit PrefersEnglish \"site language last used - for emails the owner did not trigger\"\n    }\n\n    PENDINGLOGINS {\n        int PendingLoginId PK\n        int UserId FK\n        char64 TokenHash UK \"SHA-256 hex, raw token never stored\"\n        nvarchar512 ReturnUrl \"nullable\"\n        datetime2 ExpiresAt \"15 min email link, 5 min TOTP ticket\"\n        datetime2 CreatedAt\n    }\n\n    CARTITEMS {\n        int CartItemId PK\n        int UserId FK \"signed-in customers only, a guest cart is in session\"\n        int ProductId \"no FK, admin may delete the product\"\n        int Quantity \"CHECK > 0\"\n        datetime2 AddedAt\n    }\n\n    ORDERS {\n        int OrderId PK\n        int UserId FK \"nullable: guest order, or account deleted\"\n        decimal TotalPrice \"decimal(10,2), computed server-side, includes shipping\"\n        datetime2 CreatedAt\n        tinyint Status \"0 Placed 1 Processing 2 Sent 3 Completed 4 Cancelled\"\n        tinyint DeliveryMethod \"0 Pickup, 1 Shipping\"\n        nvarchar500 ShippingAddress \"nullable, Shipping only\"\n        tinyint ShippingCarrier \"nullable: 0 PostNord 1 GLS 2 DAO Pakkeshop\"\n        decimal ShippingCost \"snapshot, 0 for pickup or free shipping\"\n        int ShippingWeightGrams \"nullable snapshot, Shipping only\"\n        int ParcelCount \"nullable snapshot, max 20 kg per parcel\"\n        nvarchar50 TrackingNumber \"nullable, typed by staff\"\n        tinyint PaymentMethod \"0 Card (demo), 1 MobilePay (demo)\"\n        nvarchar200 GuestName \"nullable, guest checkout only\"\n        nvarchar256 GuestEmail \"nullable, guest checkout only\"\n        nvarchar30 ContactPhone \"nullable, kept with the order only\"\n        bit AgeConfirmed \"ticked 16 or older - a yes/no, not an age\"\n        nvarchar200 CompanyName \"nullable, company purchase\"\n        char8 CompanyCvr \"nullable, check digit verified in code\"\n        bit PlacedInEnglish \"site language at checkout - for later emails about the order\"\n    }\n\n    ORDERITEMS {\n        int OrderItemId PK\n        int OrderId FK\n        int ProductId \"no FK, snapshot\"\n        nvarchar200 ProductName \"snapshot\"\n        decimal UnitPrice \"snapshot, decimal(10,2)\"\n        int Quantity \"CHECK > 0\"\n        bit IsAnimal \"snapshot, drives the pickup note and restock on cancel\"\n    }\n\n    PROMOTIONS {\n        int PromotionId PK\n        nvarchar200 Title\n        nvarchar500 Description\n        int DiscountPercent \"CHECK 1-100\"\n        int ProductId \"nullable, no FK\"\n        date StartDate\n        date EndDate \"CHECK >= StartDate\"\n        bit IsActive\n    }\n\n    SHIFTS {\n        int ShiftId PK\n        int UserId FK\n        datetime2 StartAt\n        datetime2 EndAt\n        nvarchar200 Note \"nullable\"\n        datetime2 CreatedAt\n    }\n\n    TIMEOFFREQUESTS {\n        int RequestId PK\n        int UserId FK\n        date StartDate\n        date EndDate\n        nvarchar500 Reason \"nullable\"\n        tinyint Status \"0 Pending, 1 Approved, 2 Denied\"\n        datetime2 RequestedAt\n        datetime2 DecidedAt \"nullable\"\n        nvarchar200 DecidedByName \"snapshot, nullable\"\n    }\n\n    AUDITLOG {\n        int AuditLogId PK\n        int ActorUserId \"nullable, no FK\"\n        nvarchar200 ActorName \"snapshot\"\n        nvarchar100 Action \"e.g. Product.Deleted\"\n        nvarchar1000 Details\n        datetime2 CreatedAt\n    }\n\n    CONTACTMESSAGES {\n        int ContactMessageId PK\n        nvarchar200 Name\n        nvarchar256 Email\n        tinyint Topic \"0 Order 1 GuineaPig 2 Accessory 3 Company 4 Other\"\n        int OrderId \"nullable, whatever the sender typed - not proof\"\n        nvarchar2000 Message\n        datetime2 CreatedAt\n    }\n\n    DONATIONS {\n        int DonationId PK\n        tinyint Kind \"0 Money (demo, never charged), 1 Products\"\n        decimal AmountKr \"nullable, Money only\"\n        nvarchar500 ItemDescription \"nullable, Products only\"\n        nvarchar200 DonorName \"nullable - anonymous is fine\"\n        nvarchar256 DonorEmail \"nullable - a thank-you email is sent here when given\"\n        nvarchar500 Message \"nullable\"\n        datetime2 CreatedAt\n    }\n\n    SEEDBATCHES {\n        nvarchar100 Name PK \"one row per one-off addition to the demo catalog\"\n        datetime2 AppliedAt\n    }\n"}, {"id": "marsvin-domain-model", "group": "Structure", "title": "Domain model", "desc": "Class diagram of the entities and enums.", "src": "classDiagram\n    direction LR\n\n    class Product {\n        <<abstract>>\n        +int ProductId\n        +string Name\n        +string Description\n        +decimal Price\n        +CanBeAddedToCart(int qty) bool\n    }\n\n    class StockProduct {\n        +string Sku\n        +AccessoryCategory Category\n        +int StockQuantity\n        +string Unit\n        +string Brand\n        +int WeightGrams\n        +string NameEn\n        +string DescriptionEn\n        +string PhotoUrl\n        +StockLevel StockLevel\n    }\n\n    class Animal {\n        +string Breed\n        +Sex Sex\n        +DateOnly DateOfBirth\n        +string Colour\n        +string CoatPrimary\n        +string CoatSecondary\n        +AnimalStatus Status\n        +int BondedWithId\n        +string Personality\n        +string PhotoUrl\n        +AgeInWeeks() int\n        +IsOldEnoughToSell() bool\n    }\n\n    class ApplicationUser {\n        +int UserId\n        +string Email\n        +string PasswordHash\n        +string DisplayName\n        +UserRole Role\n        +bool IsActive\n        +DateTime CreatedAt\n        +DateTime LastActiveAt\n        +string TotpSecret\n        +bool TotpEnabled\n        +string SecurityStamp\n        +bool PrefersEnglish\n    }\n\n    class CartLine {\n        <<read model>>\n        +int ProductId\n        +string ProductName\n        +decimal UnitPrice\n        +int Quantity\n        +bool IsAnimal\n        +string PhotoUrl\n        +int WeightGrams\n        +LineTotal() decimal\n    }\n\n    class Order {\n        <<record>>\n        +int OrderId\n        +int UserId\n        +OrderStatus Status\n        +decimal TotalPrice\n        +DateTime CreatedAt\n        +DeliveryMethod DeliveryMethod\n        +string ShippingAddress\n        +ShippingCarrier ShippingCarrier\n        +decimal ShippingCost\n        +int ShippingWeightGrams\n        +int ParcelCount\n        +string TrackingNumber\n        +PaymentMethod PaymentMethod\n        +string GuestName\n        +string GuestEmail\n        +string ContactPhone\n        +bool AgeConfirmed\n        +string CompanyName\n        +string CompanyCvr\n        +bool PlacedInEnglish\n        +ItemsTotal() decimal\n        +VatAmount() decimal\n        +ExpectedDelivery() dates\n    }\n\n    class OrderItem {\n        +int ProductId\n        +string ProductName\n        +decimal UnitPrice\n        +int Quantity\n        +bool IsAnimal\n        +LineTotal() decimal\n    }\n\n    class ShippingQuote {\n        <<record>>\n        +ShippingCarrier Carrier\n        +decimal Cost\n        +int ParcelCount\n        +DateOnly EarliestDelivery\n        +DateOnly LatestDelivery\n    }\n\n    class ShippingCalculator {\n        <<static>>\n        MaxParcelGrams = 20000\n        FreeShippingThreshold = 2000\n        +Quote(carrier, grams, orderDate, itemsTotal) ShippingQuote\n        +Cost(carrier, grams) decimal\n        +ParcelCount(grams) int\n    }\n\n    class Cvr {\n        <<static>>\n        +IsValid(text) bool\n        +Normalize(text) string\n    }\n\n    class Promotion {\n        +int PromotionId\n        +string Title\n        +int DiscountPercent\n        +int ProductId\n        +DateOnly StartDate\n        +DateOnly EndDate\n        +bool IsActive\n        +IsCurrentlyRunning(DateOnly today) bool\n    }\n\n    class Shift {\n        +int ShiftId\n        +int UserId\n        +string StaffName\n        +DateTime StartAt\n        +DateTime EndAt\n        +string Note\n    }\n\n    class TimeOffRequest {\n        +int RequestId\n        +int UserId\n        +DateOnly StartDate\n        +DateOnly EndDate\n        +TimeOffStatus Status\n        +string DecidedByName\n    }\n\n    class AuditLogEntry {\n        +int AuditLogId\n        +int ActorUserId\n        +string ActorName\n        +string Action\n        +string Details\n        +DateTime CreatedAt\n    }\n\n    class ContactMessage {\n        +int ContactMessageId\n        +string Name\n        +string Email\n        +ContactTopic Topic\n        +int OrderId\n        +string Message\n        +DateTime CreatedAt\n    }\n\n    class Donation {\n        +int DonationId\n        +DonationKind Kind\n        +decimal AmountKr\n        +string ItemDescription\n        +string DonorName\n        +string DonorEmail\n        +string Message\n    }\n\n    class ShopFact {\n        <<record, never stored>>\n        +string Da\n        +string En\n        +string ReplyDa\n        +string ReplyEn\n        +StockProduct Product\n        +Animal Animal\n        +bool Curated\n    }\n\n    class PendingLoginTicket {\n        <<record>>\n        +int UserId\n        +string ReturnUrl\n    }\n\n    class Bilingual {\n        <<record>>\n        +string Da\n        +string En\n    }\n\n    class UserRole {\n        <<enumeration>>\n        Customer\n        Employee\n        Admin\n    }\n    class Sex {\n        <<enumeration>>\n        Boar\n        Sow\n    }\n    class AnimalStatus {\n        <<enumeration>>\n        Available\n        Reserved\n        Sold\n        NotForSale\n    }\n    class AccessoryCategory {\n        <<enumeration>>\n        Hay\n        Food\n        Cage\n        House\n        Toy\n        Bedding\n        Care\n    }\n    class StockLevel {\n        <<enumeration>>\n        OutOfStock\n        LowStock\n        InStock\n    }\n    class OrderStatus {\n        <<enumeration>>\n        Placed\n        Processing\n        Sent\n        Completed\n        Cancelled\n    }\n    class DeliveryMethod {\n        <<enumeration>>\n        Pickup\n        Shipping\n    }\n    class ShippingCarrier {\n        <<enumeration>>\n        PostNord\n        Gls\n        DaoPakkeshop\n    }\n    class PaymentMethod {\n        <<enumeration>>\n        Card\n        MobilePay\n    }\n    class BuyerType {\n        <<enumeration>>\n        Private\n        Company\n    }\n    class TimeOffStatus {\n        <<enumeration>>\n        Pending\n        Approved\n        Denied\n    }\n    class ContactTopic {\n        <<enumeration>>\n        Order\n        GuineaPig\n        Accessory\n        Company\n        Other\n    }\n    class DonationKind {\n        <<enumeration>>\n        Money\n        Products\n    }\n\n    Product <|-- StockProduct\n    Product <|-- Animal\n    Animal ..> Animal : bonded partner\n\n    ApplicationUser \"1\" --> \"0..*\" CartLine : cart rows\n    ApplicationUser \"0..1\" --> \"0..*\" Order : places (a guest order has no user)\n    ApplicationUser \"1\" --> \"0..*\" Shift : is assigned\n    ApplicationUser \"1\" --> \"0..*\" TimeOffRequest : requests\n    ApplicationUser \"1\" --> \"0..1\" PendingLoginTicket : one at a time\n    ApplicationUser ..> AuditLogEntry : actor name snapshot\n\n    CartLine ..> Product : resolved by join\n    Order \"1\" *-- \"1..*\" OrderItem : snapshots\n    OrderItem ..> Product : ProductId, no FK\n    Promotion ..> Product : optional target\n    ShippingCalculator ..> ShippingQuote : produces\n    ShippingCalculator ..> CartLine : adds up WeightGrams\n    Order ..> ShippingCalculator : cost, weight and parcels stored at checkout\n    Order ..> Cvr : company number checked\n    ContactMessage ..> Order : OrderId as typed, no FK\n    ShopFact ..> StockProduct : what the chat knows\n    ShopFact ..> Animal : what the chat knows\n\n    ApplicationUser --> UserRole\n    Animal --> Sex\n    Animal --> AnimalStatus\n    StockProduct --> AccessoryCategory\n    StockProduct --> StockLevel\n    Order --> OrderStatus\n    Order --> DeliveryMethod\n    Order --> ShippingCarrier\n    Order --> PaymentMethod\n    TimeOffRequest --> TimeOffStatus\n    ContactMessage --> ContactTopic\n    Donation --> DonationKind\n"}, {"id": "marsvin-class-services", "group": "Structure", "title": "Services and stores", "desc": "Class diagram of the stores, their interfaces and DI lifetimes (incl. JWT classes).", "src": "classDiagram\n    direction TB\n\n    class Program {\n        <<composition root>>\n        DbInitializer.EnsureCreatedAndSeeded()\n        Deny by default: AuthorizeFolder(\"/\") + public list\n        AddAuthentication(cookie, 30 min idle)\n        AddJwtBearer for /api only (not the default scheme)\n        OnValidatePrincipal = AuthCookiePrincipal.RevalidateAsync\n        AddRateLimiter(\"auth\" 50/min, \"chat\" 20/min, per IP)\n        AddSession(guest cart, 60 min idle)\n        Compression for css, js, svg only\n        Security headers + CSP middleware\n        no-store for signed-in and account/cart/admin pages\n    }\n\n    class AuthCookiePrincipal {\n        <<static>>\n        IdleTimeout = 30 min\n        MaxSessionAge = 8 h\n        +Build(user, signedInAt)\n        +RevalidateAsync(context)\n    }\n\n    class JwtSettings {\n        +SigningKey - from Jwt:Key (32 bytes or more)\n        +Issuer, Audience, Lifetime = 15 min\n        +From(configuration, environment)\n        Production without a key - app refuses to start\n        Development without a key - random key per run\n    }\n    class JwtTokens {\n        <<static>>\n        +Create(user, settings, now) - HS256\n        claims: sub, name, email, role, stamp\n        +ValidateAccountAsync(context)\n        re-reads the account on every API request\n    }\n    class ApiEndpoints {\n        <<static>>\n        POST /api/auth/token - needs the login cookie\n        GET /api/me, /api/orders, /api/orders/id\n        GET /api/admin/orders - Staff policy\n        GET /api/admin/users - Admin policy\n        bearer scheme only, cookie is ignored\n    }\n\n    class ICatalog {\n        <<interface>>\n        +Animals\n        +Accessories\n        +FindAnimal(id)\n        +FindProduct(id)\n        +AvailableAnimals()\n        +AnimalGroups()\n    }\n    class ICatalogAdmin {\n        <<interface>>\n        +CreateAnimal / UpdateAnimal / DeleteAnimal\n        +CreateStockProduct / Update / Delete\n        +UpdateStockQuantity()\n        +UpdateAnimalStatus()\n    }\n    class SqlCatalog\n\n    class ICartStore {\n        <<interface>>\n        +GetLines(userId)\n        +AddOrIncrement(userId, productId, qty)\n        +SetQuantity() / RemoveLine() / Clear()\n    }\n    class SqlCartStore {\n        signed-in customer, dbo.CartItems\n    }\n    class SessionCartStore {\n        guest, server-side session\n        stores only productId + quantity\n    }\n\n    class IOrderStore {\n        <<interface>>\n        +Checkout(userId, delivery, address, carrier, payment,<br/>guest name/email, guestLines, phone, age, company, placedInEnglish)\n        +FindForUser(orderId, userId)\n        +FindById(orderId)\n        +GetOrdersForUser(userId)\n        +GetAllOrders()\n        +UpdateStatus(orderId, status, trackingNumber)\n        +Cancel(orderId, latestCancellableStatus)\n        +ClaimGuestOrder(orderId, userId, email)\n    }\n    class SqlOrderStore {\n        prices shipping itself, inside the transaction\n    }\n\n    class ShippingCalculator {\n        <<static>>\n        +Quote(carrier, grams, date, itemsTotal)\n        20 kg per parcel, free from 2,000 kr.\n    }\n\n    class IUserAccountStore {\n        <<interface>>\n        +FindByEmail() / FindById()\n        +CreateUser() / UpdateProfile()\n        +UpdatePassword() - also replaces the security stamp\n        +RotateSecurityStamp()\n        +RecordActivity() / DeleteUser()\n        +SetTotpSecret() / SetTotpEnabled()\n        +SetPrefersEnglish() - the language for emails\n        +DeleteInactiveCustomers()\n    }\n    class SqlUserAccountStore {\n        TotpSecret encrypted with IDataProtector\n    }\n\n    class IPendingLoginStore {\n        <<interface>>\n        +Create(userId, returnUrl, validFor)\n        +Consume(token)\n        +Peek(token)\n        +IsValid(token)\n    }\n    class SqlPendingLoginStore\n\n    class IInboxStore {\n        <<interface>>\n        +AddContactMessage() / GetContactMessages()\n        +AddDonation() / GetDonations()\n    }\n    class SqlInboxStore\n\n    class IPromotionStore {\n        <<interface>>\n    }\n    class IShiftStore {\n        <<interface>>\n    }\n    class ITimeOffRequestStore {\n        <<interface>>\n    }\n    class IAuditLogStore {\n        <<interface>>\n        +Record(actorId, actorName, action, details)\n        +GetRecent(count)\n    }\n\n    class IChatAssistant {\n        <<interface>>\n        +Answer(question, english)\n        +Reply(question, english, previous)\n    }\n    class KeywordChatAssistant {\n        keyword lookup - no AI service, nothing stored\n        safety stops, worked-out answers, then lookup\n    }\n    class ShopKnowledge {\n        <<static>>\n        +Build(catalog) facts\n        public shop content only\n    }\n\n    class IEmailSender {\n        <<interface>>\n        +SendAsync(to, subject, body, english)\n    }\n    class SmtpEmailSender {\n        MailKit, used when Email:Username is set\n        footer in the language of the mail\n    }\n    class LoggingEmailSender {\n        prints the link to the console, via LogSafe\n    }\n    class OrderEmails {\n        <<static>>\n        +SendStatusUpdateAsync(order, english)\n        no language given: Order.PlacedInEnglish\n    }\n\n    class SiteLanguage {\n        <<static>>\n        CookieName = marsvin-lang\n        +Read(httpContext) English, Danish or not set\n        +IsEnglish(httpContext)\n        only the values da and en count\n    }\n\n    class IRecaptchaVerifier {\n        <<interface>>\n        +VerifyAsync(token)\n    }\n    class GoogleRecaptchaVerifier {\n        skipped when no SecretKey, fails closed on errors\n    }\n\n    class LoginLockoutTracker {\n        <<singleton, in memory>>\n        +IsLockedOut(email)\n        +RegisterFailedAttempt(email)\n        +RequiresManualReset(email)\n        +Clear(email)\n    }\n\n    class Totp {\n        <<static>>\n        +GenerateSecret()\n        +BuildOtpAuthUri()\n        +ValidateCode(secret, code)\n    }\n\n    class PhotoUploadHelper {\n        <<static>>\n        +SaveAsync(file, subfolder)\n        type, first bytes and size checked, random file name\n    }\n\n    class LogSafe {\n        <<static>>\n        +Line(value)\n        +Block(value)\n    }\n\n    class InactiveAccountCleanupService {\n        <<BackgroundService, every 24h>>\n        builds its own SqlUserAccountStore\n    }\n\n    ICatalog <|.. SqlCatalog\n    ICatalogAdmin <|.. SqlCatalog\n    ICartStore <|.. SqlCartStore\n    ICartStore <|.. SessionCartStore\n    IOrderStore <|.. SqlOrderStore\n    IUserAccountStore <|.. SqlUserAccountStore\n    IPendingLoginStore <|.. SqlPendingLoginStore\n    IInboxStore <|.. SqlInboxStore\n    IChatAssistant <|.. KeywordChatAssistant\n    IEmailSender <|.. SmtpEmailSender\n    IEmailSender <|.. LoggingEmailSender\n    IRecaptchaVerifier <|.. GoogleRecaptchaVerifier\n\n    Program ..> SqlCatalog : Scoped, one instance for both interfaces\n    Program ..> ICartStore : Scoped, Sql if signed in, Session if guest\n    Program ..> SqlOrderStore : Scoped\n    Program ..> SqlUserAccountStore : Scoped\n    Program ..> SqlPendingLoginStore : Scoped\n    Program ..> SqlInboxStore : Scoped\n    Program ..> IPromotionStore : Scoped\n    Program ..> IShiftStore : Scoped\n    Program ..> ITimeOffRequestStore : Scoped\n    Program ..> IAuditLogStore : Scoped\n    Program ..> KeywordChatAssistant : Scoped\n    Program ..> LoginLockoutTracker : Singleton\n    Program ..> IEmailSender : Singleton, chosen by configuration\n    Program ..> IRecaptchaVerifier : typed HttpClient\n    Program ..> InactiveAccountCleanupService : hosted service\n    Program ..> AuthCookiePrincipal : every authenticated request\n    Program ..> JwtSettings : Singleton\n    Program ..> ApiEndpoints : MapApi()\n\n    AuthCookiePrincipal ..> IUserAccountStore : active? stamp? role?\n    ApiEndpoints ..> JwtTokens : issues the token\n    ApiEndpoints ..> IOrderStore : caller's own orders (id from the token)\n    ApiEndpoints ..> IUserAccountStore : token endpoint, admin list\n    JwtTokens ..> JwtSettings : signing key\n    JwtTokens ..> IUserAccountStore : active? stamp? role? - every request\n    AuthCookiePrincipal ..> SiteLanguage : keeps Users.PrefersEnglish current\n    OrderEmails ..> SqlOrderStore : Order.PlacedInEnglish\n    SqlOrderStore ..> ShippingCalculator : cost, weight, parcels\n    SessionCartStore ..> ICatalog : names and prices read live\n    KeywordChatAssistant ..> ShopKnowledge\n    KeywordChatAssistant ..> ShippingCalculator\n    ShopKnowledge ..> ICatalog\n    OrderEmails ..> IEmailSender\n    LoggingEmailSender ..> LogSafe\n    InactiveAccountCleanupService ..> SqlUserAccountStore\n    InactiveAccountCleanupService ..> IEmailSender\n"}, {"id": "marsvin-dfd", "group": "Structure", "title": "Data flow diagram", "desc": "Processes, data stores and trust boundaries (basis for the STRIDE table).", "src": "flowchart TB\n    subgraph INTERNET[\"Untrusted zone - the internet\"]\n        GUEST([\"Gaest<br/>browser, no account\"])\n        CUST([\"Kunde<br/>browser\"])\n        EMP([\"Medarbejder / Admin<br/>browser\"])\n        ATK([\"Attacker\"])\n    end\n\n    subgraph THIRD[\"External services\"]\n        SMTP([\"SMTP mail<br/>MailKit, or LoggingEmailSender locally<br/>every mail in Danish or English\"])\n        RECAP([\"Google reCAPTCHA<br/>siteverify - optional, off without keys\"])\n    end\n\n    subgraph SERVER[\"Trust boundary 1 - Kestrel, ASP.NET Core 9\"]\n        MW[\"0.0 Middleware<br/>HTTPS redirect, security headers + CSP,<br/>rate limiters 'auth' and 'chat', session,<br/>cookie auth re-checked per request,<br/>deny by default + [Authorize], no-store\"]\n        P1[\"1.0 Authenticate<br/>Register, Login, VerifyTotp, ConfirmLogin,<br/>ForgotPassword, ResetPassword\"]\n        P2[\"2.0 Browse catalogue<br/>Index, Marsvin, Tilbehor (search, filters),<br/>Maerker, guides, FAQ\"]\n        P3[\"3.0 Manage cart<br/>Cart/Index - guest or Customer\"]\n        P4[\"4.0 Checkout<br/>Cart/Payment, Cart/Confirmation<br/>shipping priced server-side\"]\n        P5[\"5.0 Administer shop<br/>Products, Animals, Stock, Promotions,<br/>Orders (status, tracking), Users\"]\n        P6[\"6.0 Staff scheduling<br/>Shifts, time off\"]\n        P7[\"7.0 Generate PDF<br/>QuestPDF\"]\n        P8[\"8.0 Audit logging\"]\n        P9[\"9.0 Inactive account cleanup<br/>BackgroundService, every 24h\"]\n        P10[\"10.0 Self-service account<br/>Profile: details, password, TOTP,<br/>orders, cancel, log out everywhere, delete\"]\n        P11[\"11.0 Contact and donations<br/>Kontakt, Stoet - saved for staff;<br/>a donation with an email address<br/>gets a fixed-wording thank-you\"]\n        P13[\"13.0 JSON API (JWT)<br/>POST /api/auth/token from a login cookie;<br/>/api/me, /api/orders, /api/admin/*<br/>bearer token only, 15 min, account re-read per request\"]\n        P12[\"12.0 Support chat (Pip)<br/>keyword lookup - no AI service,<br/>nothing stored\"]\n    end\n\n    subgraph DB[\"Trust boundary 2 - SQL Server LocalDB\"]\n        D1[(\"D1 Users<br/>PendingLogins<br/>TotpSecret encrypted, SecurityStamp\")]\n        D2[(\"D2 Products<br/>Animals / StockProducts\")]\n        D3[(\"D3 CartItems\")]\n        D4[(\"D4 Orders / OrderItems<br/>Promotions\")]\n        D5[(\"D5 AuditLog\")]\n        D6[(\"D6 Shifts<br/>TimeOffRequests\")]\n        D9[(\"D9 ContactMessages<br/>Donations\")]\n    end\n\n    D7[(\"D7 LoginLockoutTracker<br/>in memory, lost on restart\")]\n    D8[(\"D8 Session store<br/>guest cart, guest receipt pass<br/>in memory, 60 min idle\")]\n\n    GUEST -->|\"browse, cart, guest checkout<br/>+ marsvin-lang cookie: da or en\"| MW\n    CUST -->|\"email + password over TLS\"| MW\n    EMP -->|\"all requests\"| MW\n    ATK -.->|\"SQL injection, XSS, credential stuffing, code guessing\"| MW\n    ATK -.->|\"forced browsing to /Admin, other people's orders\"| MW\n    ATK -.->|\"tampered productId, quantity, price, shipping cost\"| MW\n    ATK -.->|\"stolen session cookie\"| MW\n    ATK -.->|\"donation form used to send mail to a stranger\"| MW\n    ATK -.->|\"forged, edited, expired or unsigned token; role rewritten to Admin\"| MW\n    EMP -->|\"Authorization: Bearer token\"| MW\n    CUST -->|\"Authorization: Bearer token\"| MW\n\n    MW --> P1\n    MW --> P2\n    MW --> P3\n    MW --> P4\n    MW --> P5\n    MW --> P6\n    MW --> P7\n    MW --> P10\n    MW --> P11\n    MW --> P12\n    MW --> P13\n    MW -->|\"every signed-in request:<br/>active? stamp? age? role?<br/>language cookie copied to the account if it changed\"| D1\n\n    P1 <--> D1\n    P1 <--> D7\n    P1 -->|\"captcha token\"| RECAP\n    P1 -->|\"confirmation and reset links\"| SMTP\n    P1 -->|\"merge guest cart, claim guest order\"| D8\n    P2 --> D2\n    P3 <--> D3\n    P3 <--> D8\n    P3 -->|\"read live prices and stock\"| D2\n    P4 -->|\"re-read prices, stock and weights<br/>UPDLOCK, HOLDLOCK\"| D2\n    P4 <--> D3\n    P4 <--> D8\n    P4 -->|\"order + snapshot items<br/>+ shipping cost, weight, parcels, language\"| D4\n    P4 -->|\"order confirmation\"| SMTP\n    P5 <--> D2\n    P5 <--> D4\n    P5 <--> D1\n    P5 --> D9\n    P5 -->|\"order status emails\"| SMTP\n    P6 <--> D6\n    P6 -->|\"shift and leave notices\"| SMTP\n    P7 --> D2\n    P9 --> D1\n    P9 -->|\"2 warnings, then delete\"| SMTP\n    P10 <--> D1\n    P10 <--> D4\n    P10 <--> D3\n    P10 -->|\"password / email change and cancel notices\"| SMTP\n    P11 -->|\"message or donation - public form\"| D9\n    P11 -->|\"donation thank-you, to the address typed in\"| SMTP\n    P12 -->|\"public catalogue only\"| D2\n    P13 -->|\"issuer, audience, expiry, HS256 checked;<br/>then active? stamp? role? from the database\"| D1\n    P13 -->|\"own orders only (user id from the token);<br/>all orders for staff\"| D4\n\n    P1 --> P8\n    P5 --> P8\n    P8 -->|\"append only in practice\"| D5\n\n    P1 -->|\"auth cookie: HttpOnly, SameSite=Lax,<br/>30 min idle, 8 h max\"| CUST\n    P4 -->|\"confirmation page\"| CUST\n    P4 -->|\"confirmation page, gated by the session's own order id\"| GUEST\n"}, {"id": "marsvin-navigation", "group": "Structure", "title": "Navigation and access control", "desc": "Which pages exist and who may open them (incl. /api and the admin dashboard).", "src": "flowchart TB\n    HOME[\"/ Index\"]\n\n    subgraph PUBLIC[\"Public - on the explicit allow-list in Program.cs (deny by default)\"]\n        MAR[\"/Marsvin<br/>photo animals first\"]\n        MDET[\"/Marsvin/Details/{id}\"]\n        TIL[\"/Tilbehor<br/>search, category / price / brand filters,<br/>sort, 24 per page\"]\n        MAE[\"/Maerker\"]\n        PAS[\"/Pasningsguide\"]\n        PASH[\"/PasningsguideHurtig\"]\n        FOD[\"/Foderliste\"]\n        FAQ[\"/Faq\"]\n        OM[\"/OmOs\"]\n        KON[\"/Kontakt<br/>contact form, rate limited\"]\n        STO[\"/Stoet<br/>donations (demo), rate limited,<br/>thank-you email if an address is given\"]\n        BET[\"/BetalingOgLevering\"]\n        PRI[\"/Privatliv\"]\n        CHAT[\"/Chat<br/>POST only - behind the Pip bubble,<br/>rate limited 20/min\"]\n        ERR[\"/Error?code= and /ServerError\"]\n    end\n\n    subgraph PDF[\"PDF downloads - QuestPDF, public\"]\n        FPDF[\"/Foderliste/Pdf\"]\n        PPDF[\"/PasningsguideHurtig/Pdf\"]\n    end\n\n    subgraph AUTHFLOW[\"Anonymous - sign-in flow, rate limited\"]\n        REG[\"/Account/Register\"]\n        LOG[\"/Account/Login\"]\n        CHK[\"/Account/CheckEmail\"]\n        CONF[\"/Account/ConfirmLogin?token=\"]\n        TOTP[\"/Account/VerifyTotp?token=\"]\n        FOR[\"/Account/ForgotPassword\"]\n        RES[\"/Account/ResetPassword?token=\"]\n        OUT[\"/Account/Logout (POST)\"]\n        DEN[\"/Account/AccessDenied\"]\n    end\n\n    subgraph SHOPPING[\"Public, but not for staff accounts - guest or Customer\"]\n        CART[\"/Cart<br/>guest: session cart, Customer: database cart\"]\n        PAY[\"/Cart/Payment<br/>details, delivery + carrier, payment\"]\n        OCON[\"/Cart/Confirmation/{orderId}<br/>own order only - status, cancel\"]\n    end\n\n    subgraph ANYUSER[\"Signed in - any role\"]\n        PRO[\"/Account/Profile<br/>details, password, TOTP, log out everywhere,<br/>staff: shifts and time off,<br/>Customer: orders, cancel, delete account\"]\n    end\n\n    subgraph STAFF[\"[Authorize(Roles=Admin,Employee)] - admin shell: left sidebar on every page\"]\n        AIDX[\"/Admin - dashboard (Oversigt)<br/>sidebar groups: Dashboard / Operations / Shop / Administration\"]\n        ASTO[\"/Admin/Stock\"]\n        AORD[\"/Admin/Orders<br/>status + tracking number\"]\n        AMSG[\"/Admin/Messages\"]\n        ADON[\"/Admin/Donations\"]\n        ASCH[\"/Admin/Schedule<br/>assign and decide: Admin only, inside the handlers\"]\n        ASHP[\"/Admin/Shop - shop overview<br/>(kept, reachable by URL; the sidebar links pages directly)\"]\n    end\n\n    subgraph ADMINONLY[\"[Authorize(Roles=Admin)]\"]\n        APRO[\"/Admin/Products + Edit\"]\n        AANI[\"/Admin/Animals + Edit\"]\n        APRM[\"/Admin/Promotions + Edit\"]\n        AUSR[\"/Admin/Users\"]\n        AEXP[\"/Admin/Users/Export/{id}\"]\n        ALOG[\"/Admin/AuditLog\"]\n        ASEC[\"/Admin/SecurityLog<br/>recorded attack attempts, severity-coded\"]\n        AADM[\"/Admin/Administration - admin overview<br/>(kept, reachable by URL)\"]\n    end\n\n    subgraph API[\"JSON API - JWT bearer, not pages (no HTML, bare 401 / 403 / 404)\"]\n        ATOK[\"POST /api/auth/token<br/>needs the website login cookie<br/>returns a 15 min token\"]\n        AME[\"/api/me, /api/orders<br/>any role - own data only\"]\n        AAORD[\"/api/admin/orders<br/>Admin and Employee\"]\n        AAUSR[\"/api/admin/users<br/>Admin only\"]\n    end\n\n    HOME --> MAR\n    HOME --> TIL\n    HOME --> PAS\n    HOME --> FAQ\n    HOME --> OM\n    HOME --> KON\n    HOME --> STO\n    MAR --> MDET\n    MAE -->|brand filter| TIL\n    PAS --> PASH\n    PASH --> PPDF\n    FOD --> FPDF\n    HOME -.->|chat bubble on every public page| CHAT\n    MDET -->|add to cart| CART\n    TIL -->|add to cart, then ask: cart or keep shopping| CART\n    CART --> PAY\n    PAY -->|guest or Customer| OCON\n    PAY -.-> BET\n    PAY -.->|guest may create an account instead| REG\n\n    LOG -->|password ok, no 2FA| CHK\n    CHK -->|emailed link| CONF\n    LOG -->|password ok, TOTP enrolled| TOTP\n    CONF -->|signs in, merges guest cart,<br/>claims the guest order| PRO\n    TOTP -->|signs in, merges guest cart| PRO\n    LOG --> REG\n    REG --> CHK\n    LOG --> FOR\n    FOR -->|emailed link| RES\n    RES --> LOG\n    PRO --> OUT\n    PRO -.->|\"signed in, ask for a token\"| ATOK\n    ATOK -->|Authorization: Bearer| AME\n    ATOK -->|Staff token| AAORD\n    ATOK -->|Admin token| AAUSR\n    PRO -->|log out everywhere| LOG\n\n    %% Both login-completion flows land a staff account on the dashboard\n    %% (a Customer lands on the storefront home instead).\n    CONF -.->|Role = staff -> dashboard| AIDX\n    TOTP -.->|Role = staff -> dashboard| AIDX\n\n    %% The admin shell's left sidebar (shown on every /Admin page) links the\n    %% dashboard straight to each admin page; every page also has one\n    %% Back to dashboard button. The two overview pages are kept but no longer\n    %% part of the primary navigation.\n    AIDX -->|sidebar| ASTO\n    AIDX -->|sidebar| AORD\n    AIDX -->|sidebar| AMSG\n    AIDX -->|sidebar| ADON\n    AIDX -->|sidebar| ASCH\n    AIDX -->|sidebar: Admin only| APRO\n    AIDX -->|sidebar: Admin only| AANI\n    AIDX -->|sidebar: Admin only| APRM\n    AIDX -->|sidebar: Admin only| AUSR\n    AIDX -->|sidebar: Admin only| ALOG\n    AIDX -->|sidebar: Admin only| ASEC\n    AIDX -.->|kept, by URL| ASHP\n    AIDX -.->|kept, by URL| AADM\n    AUSR --> AEXP\n\n    ANYUSER -.->|not signed in, idle 30 min,<br/>8 h old, or password changed| LOG\n    ADMINONLY -.->|Employee| DEN\n    STAFF -.->|Customer| DEN\n    ERR -.->|404, expired form 400, 429, 403| HOME\n"}, {"id": "marsvin-deployment", "group": "Structure", "title": "Deployment", "desc": "What runs where: browser, web app, SQL Server, SMTP, reCAPTCHA.", "src": "flowchart TB\n    subgraph CLIENT[\"Device: customer, guest or staff browser\"]\n        BROWSER[\"HTML + CSS + 12 small single-purpose JS files<br/>no inline script or style, no web fonts, no CDN<br/>CSP: script-src 'self' (+ Google for reCAPTCHA)<br/>localStorage holds only the language choice,<br/>mirrored in a marsvin-lang cookie (da / en) for emails\"]\n        AUTHAPP[\"Authenticator app<br/>(only for TOTP-enrolled accounts)\"]\n    end\n\n    subgraph DEV[\"Device: developer machine - Windows, local only\"]\n        subgraph KESTREL[\"Kestrel - http://localhost:5080\"]\n            APP[\"marsvin-web<br/>ASP.NET Core 9 Razor Pages\"]\n            PAGES[\"Pages - 48 routes<br/>PageModels<br/>+ JSON API under /api (JWT bearer)\"]\n            STORES[\"Data - 10 Sql*Store classes<br/>ADO.NET, parameterised\"]\n            CHATBOT[\"KeywordChatAssistant (Pip)<br/>in-process lookup - no AI service\"]\n            BG[\"InactiveAccountCleanupService<br/>BackgroundService\"]\n            LOCK[\"LoginLockoutTracker<br/>in-memory singleton\"]\n            SESS[\"Session store<br/>guest cart + receipt pass, in memory\"]\n            APP --- PAGES\n            PAGES --- STORES\n            PAGES --- CHATBOT\n            APP --- BG\n            PAGES --- LOCK\n            PAGES --- SESS\n        end\n        subgraph SQL[\"SQL Server LocalDB\"]\n            DBASE[(\"MarsvinDb<br/>15 tables<br/>Trusted_Connection - full rights (known gap)\")]\n        end\n        KEYS[\"Data-protection key ring<br/>LocalApplicationData<br/>encrypts Users.TotpSecret\"]\n        UPLOADS[\"wwwroot/img<br/>page photos, 67 product photos, animal photos,<br/>brand logos, admin uploads (type + first bytes checked)\"]\n        SECRETS[\"User Secrets<br/>Email:Username / Password<br/>Recaptcha:SecretKey<br/>Jwt:Key (required outside Development)\"]\n        TESTS[\"marsvin-web.Tests - 780 tests<br/>xUnit + WebApplicationFactory<br/>MarsvinDb_Test, MarsvinDb_WebTest\"]\n    end\n\n    subgraph EXT[\"External - both optional\"]\n        SMTPSVC[\"SMTP over TLS<br/>MailKit\"]\n        GRECAP[\"Google reCAPTCHA v2<br/>siteverify\"]\n    end\n\n    BROWSER -->|\"HTTPS, HSTS outside Development<br/>auth cookie HttpOnly + SameSite=Lax, 30 min idle / 8 h max<br/>css, js, svg compressed - HTML not (BREACH)\"| APP\n    AUTHAPP -.->|\"6-digit code typed by the user\"| BROWSER\n    STORES -->|\"Microsoft.Data.SqlClient<br/>SqlCommand + SqlParameter\"| DBASE\n    CHATBOT -->|\"public catalogue only, via ICatalog\"| STORES\n    STORES -.->|\"IDataProtector\"| KEYS\n    PAGES -->|\"PhotoUploadHelper\"| UPLOADS\n    APP -.->|\"read at startup\"| SECRETS\n    BG -->|\"inactivity warnings\"| SMTPSVC\n    PAGES -->|\"login links, order confirmations,<br/>order status, security notices,<br/>donation thank-you - in Danish or English\"| SMTPSVC\n    PAGES -->|\"captcha token, only if keys are set\"| GRECAP\n    TESTS -.->|\"boots the app in-process\"| APP\n\n    NOTE[\"Nothing here costs money to run:<br/>QuestPDF renders the PDFs in-process,<br/>the chat is a lookup inside the app,<br/>payment and donations are demos.\"]\n    APP --- NOTE\n"}, {"id": "marsvin-sequence-register", "group": "Sequence", "title": "Register", "desc": "Sign-up with reCAPTCHA, password policy and e-mail confirmation.", "src": "sequenceDiagram\n    autonumber\n    actor K as Besogende\n    participant RM as RegisterModel\n    participant RC as IRecaptchaVerifier\n    participant US as IUserAccountStore\n    participant PL as IPendingLoginStore\n    participant ES as IEmailSender\n    participant CM as ConfirmLoginModel\n\n    K->>RM: POST /Account/Register (email, name, password, confirm, captcha token)\n    Note over RM: [EnableRateLimiting(\"auth\")] - 50 per minute per IP\n\n    alt ModelState invalid\n        RM-->>K: Page() with validation errors\n        Note over RM: Server rule: StringLength(100, MinimumLength = 8)<br/>and the two passwords must match.<br/>The strength meter on the form is client-side guidance only.\n    else valid\n        RM->>RC: VerifyAsync(captcha token)\n        alt captcha rejected\n            RM-->>K: \"Bekraeft at du ikke er en robot\"\n        else captcha ok\n            RM->>RM: PasswordHasher.HashPassword (PBKDF2)\n            RM->>US: CreateUser(email, hash, name, UserRole.Customer)\n            Note over RM,US: Self-registration can only ever create Customer.<br/>Employee and Admin are seeded or created from /Admin/Users.\n\n            alt email already registered\n                US-->>RM: false\n                RM-->>K: \"Der findes allerede en konto med den e-mail\"\n            else created\n                US-->>RM: true\n                RM->>US: FindByEmail(email)\n                US-->>RM: ApplicationUser\n                RM->>PL: Create(userId, safeReturnUrl, 15 min)\n                PL-->>RM: raw token (hash stored)\n                RM->>US: SetPrefersEnglish(userId), if the site is in English\n                RM->>ES: SendAsync(\"Bekraeft din konto\" or \"Confirm your account\")\n                RM-->>K: Redirect to /Account/CheckEmail?purpose=register\n            end\n        end\n    end\n\n    K->>CM: GET /Account/ConfirmLogin?token=...\n    CM->>PL: Consume(token)\n    CM->>US: RecordActivity(userId)\n    CM->>CM: SignInAsync (auth cookie with the security stamp)\n    CM->>CM: merge the guest cart, and move a guest order just placed<br/>in this session into the new account, if the email matches\n    CM-->>K: signed in, redirected\n\n    Note over K,CM: Registration does not sign you in.<br/>The same proof-of-inbox step as login<br/>is what proves the address is yours.<br/>The payment page offers a guest this route:<br/>the cart, and the order just placed, come along.\n"}, {"id": "marsvin-sequence-login", "group": "Sequence", "title": "Login", "desc": "Password, then e-mail link or TOTP, lockout and security events.", "src": "sequenceDiagram\n    autonumber\n    actor K as Kunde\n    participant LM as LoginModel\n    participant RL as RateLimiter (\"auth\")\n    participant RC as IRecaptchaVerifier\n    participant LO as LoginLockoutTracker\n    participant US as IUserAccountStore\n    participant PL as IPendingLoginStore\n    participant ES as IEmailSender\n    participant TM as VerifyTotpModel\n    participant CM as ConfirmLoginModel\n\n    Note over K,CM: Two steps. A correct password alone never signs anyone in:<br/>the second step is either an emailed link or, if the account has 2FA, a TOTP code.\n\n    K->>LM: POST /Account/Login (email, password, captcha token)\n    LM->>RL: 50 requests per minute per IP?\n    alt over the limit\n        RL-->>K: 429 Too Many Requests\n    else within the limit\n        LM->>RC: VerifyAsync(captcha token)\n        Note over RC: Google siteverify. Skipped when no SecretKey is set,<br/>fails closed if Google is unreachable.\n        alt captcha rejected\n            LM-->>K: \"Bekraeft at du ikke er en robot\"\n        else captcha ok\n            LM->>LO: IsLockedOut(email)\n            alt locked out\n                LO-->>LM: true\n                LM-->>K: \"Too many attempts\" or, after 5 failures,<br/>\"reset your password to unlock\"\n            else not locked\n                LM->>US: FindByEmail(email)\n                US-->>LM: ApplicationUser or null\n                LM->>LM: PasswordHasher.VerifyHashedPassword\n\n                alt wrong password, unknown email, or inactive account\n                    LM->>LO: RegisterFailedAttempt(email)\n                    Note over LO: Delay grows 3^n seconds (cap 5 min).<br/>3rd failure: notice emailed to the owner, in the<br/>owner's stored language (Users.PrefersEnglish).<br/>5th failure: locked until a password reset.\n                    LM-->>K: \"Forkert e-mail eller adgangskode\"\n                    Note over LM: One message for all three cases -<br/>no account enumeration.\n                else password correct\n                    LM->>LO: Clear(email)\n                    LM->>LM: IsSafeLocalUrl(returnUrl)?\n                    alt TotpEnabled\n                        LM->>PL: Create(userId, safeReturnUrl, 5 min)\n                        PL-->>LM: raw token (SHA-256 hash stored, never emailed)\n                        LM-->>K: Redirect to /Account/VerifyTotp?token=...\n                    else no 2FA\n                        LM->>PL: Create(userId, safeReturnUrl, 15 min)\n                        PL-->>LM: raw token (SHA-256 hash stored)\n                        LM->>ES: SendAsync(confirmation link) - Danish or English,<br/>after the marsvin-lang cookie of this browser\n                        LM-->>K: Redirect to /Account/CheckEmail\n                    end\n                end\n            end\n        end\n    end\n\n    alt second step: TOTP code\n        K->>TM: POST /Account/VerifyTotp (token, 6-digit code)\n        TM->>PL: Peek(token)\n        Note over PL: Peek does not spend the token, so a typo<br/>can be retried until it expires.\n        TM->>LO: IsLockedOut(email)\n        TM->>TM: Totp.ValidateCode(secret, code)<br/>HMAC-SHA1, 30 s step, plus or minus one step\n        alt wrong code\n            TM->>LO: RegisterFailedAttempt(email)\n            TM-->>K: \"Forkert kode\"\n        else code ok\n            TM->>LO: Clear(email)\n            TM->>PL: Consume(token)\n            TM->>US: RecordActivity(userId)\n            TM->>TM: merge the guest cart into the account's cart\n            TM->>TM: SignInAsync - auth cookie with the account's security stamp<br/>HttpOnly, SameSite=Lax, 30 min idle, 8 h max\n            TM-->>K: LocalRedirect(returnUrl), else staff -> /Admin (dashboard), Customer -> /Index\n        end\n    else second step: emailed link\n        K->>CM: GET /Account/ConfirmLogin?token=...\n        CM->>PL: Consume(token)\n        Note over PL: Single use. Expired, already used<br/>or unknown all return null.\n        alt token invalid\n            PL-->>CM: null\n            CM-->>K: \"Log ind igen\"\n        else token valid\n            PL-->>CM: ticket(userId, returnUrl)\n            CM->>US: FindById(userId)\n            alt account gone or deactivated meanwhile\n                CM-->>K: \"Log ind igen\"\n            else account active\n                CM->>US: RecordActivity(userId)\n                CM->>CM: merge the guest cart into the account's cart,<br/>claim a guest order just placed in this session<br/>(same session AND same email)\n                CM->>CM: SignInAsync - auth cookie with the account's security stamp<br/>HttpOnly, SameSite=Lax, 30 min idle, 8 h max\n                CM-->>K: LocalRedirect(returnUrl), else staff -> /Admin (dashboard), Customer -> /Index\n            end\n        end\n    end\n\n    Note over K,CM: The \"check your email\" tab polls /Account/Profile (check-email.js)<br/>and moves on by itself once another tab has confirmed the link.<br/>From here on, every request re-checks the account - see the session-check diagram.\n"}, {"id": "marsvin-sequence-password-reset", "group": "Sequence", "title": "Forgot / reset password", "desc": "Single-use token by e-mail and the new password.", "src": "sequenceDiagram\n    autonumber\n    actor K as Kunde\n    participant FM as ForgotPasswordModel\n    participant RC as IRecaptchaVerifier\n    participant US as IUserAccountStore\n    participant PL as IPendingLoginStore\n    participant ES as IEmailSender\n    participant RM as ResetPasswordModel\n    participant LO as LoginLockoutTracker\n\n    K->>FM: POST /Account/ForgotPassword (email, captcha token)\n    Note over FM: [EnableRateLimiting(\"auth\")]\n    FM->>RC: VerifyAsync(captcha token)\n    alt captcha rejected\n        FM-->>K: \"Bekraeft at du ikke er en robot\"\n    else captcha ok\n        FM->>US: FindByEmail(email)\n\n        alt account exists and is active\n            US-->>FM: ApplicationUser\n            FM->>PL: Create(userId, null, 15 min)\n            PL-->>FM: raw token (SHA-256 hash stored)\n            FM->>ES: SendAsync(reset link) - Danish or English, after the browser\n        else no such account, or inactive\n            US-->>FM: null\n            Note over FM: Nothing is sent - and nothing<br/>in the response says so.\n        end\n\n        FM-->>K: Redirect to /Account/CheckEmail?purpose=reset\n        Note over FM,K: Identical response either way.<br/>Otherwise the form becomes a way to test<br/>which email addresses are registered.\n    end\n\n    K->>RM: GET /Account/ResetPassword?token=...\n    RM->>PL: IsValid(token)\n    Note over RM,PL: Peek only. The token is not spent here,<br/>so sitting on the form for a while<br/>does not invalidate it.\n    alt token missing or expired\n        RM-->>K: \"Linket er udlobet\"\n    else token valid\n        RM-->>K: new-password form\n\n        K->>RM: POST (new password, confirm)\n        RM->>PL: IsValid(token) again\n        RM->>RM: validate ModelState (min 8 characters, must match)\n        RM->>PL: Consume(token)\n        Note over PL: Spent here, at the point of use.<br/>Single redemption.\n        alt token already used or account gone\n            RM-->>K: \"Linket er udlobet\"\n        else ok\n            RM->>RM: PasswordHasher.HashPassword\n            RM->>US: UpdatePassword(userId, hash)\n            Note over RM,US: The same UPDATE replaces Users.SecurityStamp:<br/>every session signed in with the old password -<br/>a stolen cookie included - ends on its next request.\n            RM->>LO: Clear(email)\n            Note over RM,LO: The only thing that lifts a hard lockout<br/>(5 failed attempts).\n            RM->>ES: SendAsync(\"Din adgangskode er aendret\"<br/>or \"Your password has been changed\")\n            Note over RM,ES: ASVS 2.5.5 - every change to a sign-in factor<br/>is notified to the account owner.\n            RM-->>K: Redirect to /Account/Login with toast\n        end\n    end\n"}, {"id": "marsvin-sequence-totp-enrollment", "group": "Sequence", "title": "2FA enrol / disable", "desc": "Authenticator app setup with the encrypted secret.", "src": "sequenceDiagram\n    autonumber\n    actor K as Bruger (signed in)\n    participant PM as ProfileModel\n    participant US as IUserAccountStore\n    participant DB as MarsvinDb\n    participant AP as Authenticator app\n\n    Note over K,AP: Optional second factor. Enrollment has two steps on purpose -<br/>a secret exists before 2FA is switched on, so nobody is locked out<br/>by a QR code they never scanned.\n\n    K->>PM: POST Profile?handler=StartTotpEnrollment\n    PM->>PM: Totp.GenerateSecret()<br/>20 random bytes, Base32\n    PM->>US: SetTotpSecret(userId, secret)\n    US->>US: encrypt with IDataProtector\n    US->>DB: UPDATE Users SET TotpSecret = ciphertext, TotpEnabled = 0\n    PM-->>K: Redirect to /Account/Profile\n\n    K->>PM: GET /Account/Profile\n    PM->>US: FindById(userId)\n    US-->>PM: user with a pending secret, TotpEnabled = false\n    PM->>PM: BuildOtpAuthUri(secret, email)<br/>QrCode.ToDataUri(uri)\n    PM-->>K: QR code + secret in text form\n\n    K->>AP: scans the QR code\n    AP-->>K: 6-digit code, new every 30 seconds\n\n    K->>PM: POST Profile?handler=ConfirmTotp (code)\n    PM->>US: FindById(userId)\n    PM->>PM: Totp.ValidateCode(secret, code)\n    alt wrong code\n        PM-->>K: Redirect with error \"Forkert kode\"\n        Note over PM: TotpEnabled stays false,<br/>login is unchanged.\n    else code ok\n        PM->>US: SetTotpEnabled(userId, true)\n        US->>DB: UPDATE Users SET TotpEnabled = 1\n        PM-->>K: toast \"2FA er nu aktiveret\"\n    end\n\n    Note over K,DB: From the next login on, a correct password goes straight to<br/>/Account/VerifyTotp instead of sending an email link.\n\n    K->>PM: POST Profile?handler=DisableTotp (currentPassword)\n    PM->>PM: verify the current password\n    alt wrong password\n        PM-->>K: error, 2FA stays on\n    else password ok\n        PM->>US: SetTotpSecret(userId, null)\n        US->>DB: UPDATE Users SET TotpSecret = NULL, TotpEnabled = 0\n        PM-->>K: toast \"2FA er deaktiveret\"\n    end\n"}, {"id": "marsvin-sequence-session-check", "group": "Sequence", "title": "Session check", "desc": "What is verified on every request (security stamp, timeouts).", "src": "sequenceDiagram\n    autonumber\n    actor U as Signed-in user\n    participant CK as Cookie authentication\n    participant AP as AuthCookiePrincipal.RevalidateAsync\n    participant US as IUserAccountStore\n    participant DB as MarsvinDb\n    participant AZ as Authorization\n    participant PG as The requested page\n\n    Note over U,PG: Runs on EVERY request that carries the login cookie, before any page code.<br/>The cookie is only a snapshot from sign-in - this is what keeps it true.\n\n    U->>CK: any request + auth cookie\n    CK->>CK: decrypt and check the signature\n    alt cookie missing, tampered with, or idle for more than 30 minutes\n        CK-->>U: treated as not signed in\n    else cookie valid\n        CK->>AP: OnValidatePrincipal(principal)\n        AP->>US: FindById(userId from the cookie)\n        US->>DB: SELECT ... FROM Users WHERE UserId = @UserId\n        DB-->>US: account, or nothing\n        US-->>AP: ApplicationUser or null\n\n        alt account deleted, or IsActive = false\n            AP-->>CK: RejectPrincipal + SignOut\n            Note over AP: An admin deactivating an account<br/>takes effect on its very next click.\n        else the cookie's stamp differs from Users.SecurityStamp\n            AP-->>CK: RejectPrincipal + SignOut\n            Note over AP: The stamp is replaced when the password is changed<br/>or reset, and by \"log out everywhere\".<br/>Every older cookie - a stolen one included - dies here.\n        else signed in more than 8 hours ago\n            AP-->>CK: RejectPrincipal + SignOut\n            Note over AP: The 30 minutes are sliding, so on their own a session<br/>in constant use would never end. This is the hard limit.\n        else role, name or email changed since sign-in\n            AP->>AP: Build(user, original sign-in time)\n            AP-->>CK: ReplacePrincipal, renew the cookie\n            Note over AP: A demoted Admin loses /Admin on this request.<br/>The sign-in time is kept - a change never buys more time.\n        else nothing changed\n            AP-->>CK: keep the principal<br/>(cookie renewed, so the 30 minutes count from this request)\n        end\n\n        opt session kept, and the marsvin-lang cookie (da / en) differs from Users.PrefersEnglish\n            AP->>US: SetPrefersEnglish(userId, english)\n            Note over AP,US: So emails this user does not trigger themselves<br/>are in the language they read the site in.<br/>Any other cookie value is ignored.\n        end\n\n        CK->>AZ: principal, or anonymous\n        alt page is on the public list\n            AZ->>PG: run the handler\n        else not signed in\n            AZ-->>U: Redirect to /Account/Login\n        else signed in, role not allowed on this page\n            AZ-->>U: Redirect to /Account/AccessDenied\n        else allowed\n            AZ->>PG: run the handler\n            PG-->>U: page, sent with Cache-Control: no-store\n            Note over PG,U: So the Back button cannot bring a profile<br/>or an order back after logging out.\n        end\n    end\n\n    Note over U,PG: Deny by default: a page is public only if Program.cs lists it.<br/>A new page that forgets its [Authorize] ends up behind the login.\n"}, {"id": "marsvin-sequence-add-to-cart", "group": "Sequence", "title": "Add to cart", "desc": "Guest cart in session, account cart in SQL.", "src": "sequenceDiagram\n    autonumber\n    actor K as Kunde or Gaest\n    participant CM as Cart/Index (OnPostAdd)\n    participant CA as ICatalog\n    participant CS as ICartStore\n    participant DB as MarsvinDb or Session\n\n    Note over K,CS: No login needed. ICartStore is chosen per request in Program.cs:<br/>SqlCartStore (dbo.CartItems) when signed in, SessionCartStore for a guest.\n\n    K->>CM: POST /Cart?handler=Add (productId, quantity, returnUrl,<br/>confirmNotAlone, companionNote)\n\n    alt signed in as Employee or Admin\n        CM-->>K: error message, back to returnUrl\n        Note over CM: The pages already hide the button from staff -<br/>checked again here, since anyone can POST directly.\n    else guest or Customer\n        CM->>CA: FindAnimal(productId)\n        CA-->>CM: Animal or null\n\n        alt it is an animal\n            CM->>CM: animal.CanBeAddedToCart(1)\n            Note over CM: Status = Available and at least 4 weeks old.\n            alt cannot be added\n                CM-->>K: error toast, back to returnUrl\n            else unbonded animal without confirmNotAlone and companionNote\n                CM-->>K: error: only sold alone if it will not live alone\n                Note over CM: Checked server-side - a checkbox in the HTML<br/>is exactly as trustworthy as no checkbox.\n            else ok\n                CM->>CS: AddOrIncrement(userId, productId, 1)\n                opt animal has BondedWithId and partner not already in the cart\n                    CM->>CA: FindAnimal(partnerId)\n                    CM->>CS: AddOrIncrement(userId, partnerId, 1)\n                    Note over CM,CS: The pair moves in together - both are added.\n                end\n                CM-->>K: back to returnUrl, with a box asking:<br/>go to the cart, or keep shopping?\n            end\n        else it is an accessory\n            CM->>CA: Accessories lookup by productId\n            alt not found or quantity < 1\n                CM-->>K: error toast\n            else found\n                CM->>CS: GetLines(userId)\n                CM->>CM: CanBeAddedToCart(quantityInCart + quantity)\n                alt more than StockQuantity\n                    CM-->>K: \"Der er ikke N styk tilbage\"\n                else ok\n                    CM->>CS: AddOrIncrement(userId, productId, quantity)\n                    alt signed in\n                        CS->>DB: MERGE dbo.CartItems - insert or bump Quantity\n                        Note over CS,DB: UQ_CartItems_UserProduct keeps<br/>one row per user per product.\n                    else guest\n                        CS->>DB: session: productId + quantity only\n                    end\n                    CM-->>K: back to returnUrl, with a box asking:<br/>go to the cart, or keep shopping?\n                end\n            end\n        end\n    end\n\n    Note over CM,DB: The redirect target is only used if IsSafeLocalUrl(returnUrl)<br/>(one leading slash, no //host) - otherwise /Cart.<br/>Either cart stores only productId and quantity - prices are read live<br/>and re-read inside the checkout transaction.<br/>A guest's cart is merged into the account's cart at login.\n"}, {"id": "marsvin-sequence-checkout", "group": "Sequence", "title": "Checkout", "desc": "Transaction, stock locking, order and order lines (guest or customer).", "src": "sequenceDiagram\n    autonumber\n    actor K as Kunde or Gaest\n    participant PM as PaymentModel\n    participant CS as ICartStore\n    participant OS as SqlOrderStore\n    participant SC as ShippingCalculator\n    participant DB as MarsvinDb\n    participant SE as Session\n    participant ES as IEmailSender\n    participant CF as ConfirmationModel\n\n    Note over PM,DB: As built. No payment provider is contacted - the card or MobilePay<br/>choice is stored on the order, and card details are only checked for shape.<br/>No account is needed: ICartStore is the database cart for a Customer<br/>and the session cart for a guest.\n\n    K->>PM: POST /Cart/Payment (name + email if guest, phone, buyer type,<br/>company + CVR, age box, delivery, address, carrier,<br/>paymentMethod, card fields)\n    Note over PM: Public page, but Employee and Admin<br/>are turned away - staff accounts cannot buy.\n    PM->>CS: GetLines(userId)\n    CS-->>PM: CartLine list (live prices and weights)\n\n    alt cart empty\n        PM-->>K: Redirect to /Cart\n    else something that applies is missing or malformed\n        Note over PM: Only what applies is required: guest name + email,<br/>phone and address if Shipping, age box if an animal,<br/>company name + CVR check digit if Company,<br/>card digits if Card (spaces and slash optional).\n        PM-->>K: Page() with the fields marked\n    else valid\n        PM->>OS: Checkout(userId or null, delivery, address, carrier, paymentMethod,<br/>guestName, guestEmail, guestLines, phone, ageConfirmed, company, cvr, placedInEnglish)\n        OS->>DB: BeginTransaction\n        OS->>DB: SELECT CartItems JOIN Products / Animals / StockProducts\n        DB-->>OS: lines with DB prices and weights\n        Note over OS: A guest has no CartItems rows, so the lines<br/>PaymentModel already resolved are passed in<br/>and re-validated against the database below.\n\n        alt cart empty\n            OS-->>PM: Fail(\"Din kurv er tom\")\n        else Shipping but all lines are animals, or no address\n            OS->>DB: Rollback\n            OS-->>PM: Fail(reason)\n            Note over OS: Re-checked here, never trusted from the form\n        else\n            loop each cart line\n                OS->>DB: SELECT ... WITH (UPDLOCK, HOLDLOCK)\n                Note over OS,DB: Animal: Status = Available and at least 4 weeks old.<br/>StockProduct: StockQuantity >= qty.<br/>The lock stops two checkouts racing for the last unit.\n            end\n\n            alt any line invalid\n                OS->>DB: Rollback\n                OS-->>PM: Fail(reason)\n            else all lines valid\n                opt Shipping\n                    OS->>SC: Quote(carrier, weight of the shippable lines, today, their total)\n                    SC-->>OS: cost, parcel count (max 20 kg each)\n                    Note over OS,SC: The form chooses a carrier - never a price.<br/>Free when the shipped accessories reach 2,000 kr.\n                end\n                OS->>DB: INSERT Orders (Status = Placed, TotalPrice = DB prices + shipping,<br/>ShippingCost / WeightGrams / ParcelCount snapshots,<br/>guest name + email or UserId, phone, age, company, PlacedInEnglish)\n                OS->>DB: INSERT OrderItems (ProductName, UnitPrice, IsAnimal snapshots)\n                loop each cart line\n                    OS->>DB: Animal to Sold, or StockQuantity = StockQuantity - qty\n                end\n                OS->>DB: DELETE CartItems for this user\n                OS->>DB: Commit\n                OS-->>PM: Ok(order)\n                PM->>CS: Clear(userId)\n                opt guest\n                    PM->>SE: SetInt32(\"GuestOrderId\", orderId)\n                    Note over PM,SE: The guest's receipt pass: only this browser's<br/>session ever holds this order id.\n                end\n                PM->>ES: SendAsync(\"Ordrebekraeftelse\" or \"Order confirmation\")\n                Note over PM,ES: Written in the language the order was placed in:<br/>the marsvin-lang cookie of this request, saved on the order.\n                PM-->>K: Redirect to /Cart/Confirmation/{orderId}\n                K->>CF: GET /Cart/Confirmation/{orderId}\n                alt signed in\n                    CF->>OS: FindForUser(orderId, userId)\n                    Note over CF,OS: Takes both ids, so changing orderId in the URL<br/>to someone else's order just returns 404 (no IDOR).\n                else guest\n                    CF->>SE: GetInt32(\"GuestOrderId\") == orderId?\n                    CF->>OS: FindById(orderId), only on a match\n                end\n                CF-->>K: receipt: status steps, delivery, expected delivery,<br/>pickup note if an animal is in a shipped order\n            end\n        end\n        PM-->>K: on Fail: Redirect to /Cart with the error message\n    end\n\n    Note over OS,DB: One transaction covers validation, shipping price, insert,<br/>stock change and cart clear - any failure rolls the whole thing back.\n"}, {"id": "marsvin-sequence-order-status", "group": "Sequence", "title": "Order status and cancelling", "desc": "How staff move an order forward, and cancelling.", "src": "sequenceDiagram\n    autonumber\n    actor S as Staff (Admin or Employee)\n    actor K as Kunde\n    participant AO as Admin/Orders\n    participant PC as Profile or Confirmation\n    participant OS as SqlOrderStore\n    participant DB as MarsvinDb\n    participant AL as IAuditLogStore\n    participant OE as OrderEmails\n\n    Note over S,OE: What happens to an order after checkout.\n\n    S->>AO: POST status (orderId, new status, tracking number)\n    Note over AO: [Authorize(Roles = \"Admin,Employee\")]<br/>The tracking number may only hold letters, digits, spaces and dashes,<br/>and is dropped for a pickup order whatever the form says.\n    AO->>OS: FindById(orderId)\n\n    alt new status is Cancelled\n        AO->>OS: Cancel(orderId, latest = Processing)\n        Note over AO,OS: Staff may cancel until the order has been sent.\n    else any other status\n        AO->>OS: UpdateStatus(orderId, status, trackingNumber)\n        OS->>DB: UPDATE Orders SET Status, TrackingNumber<br/>WHERE OrderId = @id AND Status <> Cancelled\n        Note over OS,DB: A cancelled order is final - its items<br/>are already back on sale.\n    end\n\n    alt nothing changed (already sent, or already cancelled)\n        AO-->>S: error message\n    else changed\n        AO->>AL: Record(\"Order.StatusChanged\", \"#id: old -> new\")\n        AO->>OE: SendStatusUpdateAsync(order)\n        Note over AO,OE: Staff triggered it, so the mail is written in<br/>Orders.PlacedInEnglish - the language the buyer ordered in,<br/>not the language of the staff member's browser.\n        OE-->>K: email: being prepared / sent, with tracking number /<br/>ready for pickup / delivered / cancelled\n        AO-->>S: \"order updated, the customer has been emailed\"\n    end\n\n    K->>PC: POST cancel (orderId)\n    Note over PC: From the receipt or the order history.<br/>First the order is looked up the same way as for viewing it:<br/>it has to be the caller's own.\n    PC->>OS: Cancel(orderId, latest = Placed)\n    Note over PC,OS: The buyer may cancel only until staff<br/>have started preparing the order.\n    OS->>DB: BeginTransaction\n    OS->>DB: UPDATE Orders SET Status = Cancelled<br/>WHERE OrderId = @id AND Status <= @latest\n    Note over OS,DB: One statement both checks and changes - a second click,<br/>or two requests at once, find nothing left to cancel.\n    alt no row changed\n        OS->>DB: Rollback\n        OS-->>PC: false\n        PC-->>K: \"can no longer be cancelled\"\n    else cancelled\n        loop each order line\n            OS->>DB: accessory: StockQuantity = StockQuantity + qty<br/>animal: Status Sold -> Available\n        end\n        OS->>DB: Commit\n        OS-->>PC: true\n        PC->>OE: SendStatusUpdateAsync(order, language of the buyer's own browser)\n        OE-->>K: email: order cancelled\n        PC-->>K: order shown as Cancelled\n    end\n\n    Note over S,OE: Cancelled is the highest status number, so \"may still be cancelled\"<br/>is a plain Status <= latest comparison that a cancelled order can never pass.\n"}, {"id": "marsvin-sequence-donation", "group": "Sequence", "title": "Donation", "desc": "A demo donation and its thank-you e-mail.", "src": "sequenceDiagram\n    autonumber\n    actor G as Giver (guest or signed in)\n    participant SM as StoetModel\n    participant RL as RateLimiter (\"auth\")\n    participant RC as IRecaptchaVerifier\n    participant IS as IInboxStore\n    participant DB as MarsvinDb\n    participant ES as IEmailSender\n    actor ST as Staff\n\n    Note over G,ES: A public form. A money donation is a demo like the checkout:<br/>it is recorded, never charged, and no card details are asked for.\n\n    G->>SM: POST /Stoet (kind, amount or item description,<br/>name, email, greeting, captcha token)\n    SM->>RL: 50 requests per minute per IP?\n    alt over the limit\n        RL-->>G: 429 Too Many Requests\n    else within the limit\n        alt Money: amount missing or outside 10 - 10,000 kr.\n            SM-->>G: Page() with the field marked\n        else Products: description, name or email missing\n            SM-->>G: Page() with the fields marked\n            Note over SM: Only the fields of the chosen kind are required -<br/>a money donation may be anonymous.\n        else valid\n            SM->>RC: VerifyAsync(captcha token)\n            alt captcha rejected\n                SM-->>G: \"Bekraeft at du ikke er en robot\"\n            else captcha ok\n                SM->>IS: AddDonation(donation)\n                IS->>DB: INSERT Donations\n                Note over SM,DB: Only the fields that belong to the chosen kind are kept,<br/>whatever else the form posted.\n\n                opt an email address was given\n                    SM->>SM: IsEnglish()? - the marsvin-lang cookie of this request\n                    SM->>ES: SendAsync(donor email, \"Tak for din donation til Marsvin\"<br/>or \"Thank you for your donation to Marsvin\")\n                    Note over SM,ES: Fixed wording: the amount, or the shop's address and opening hours.<br/>The donor's own free text (what they offer, their greeting) is NOT repeated,<br/>and the name is kept to one line - the address is whatever was typed in,<br/>so the form must not become a way to send a stranger your own wording.\n                    alt sending failed\n                        Note over SM: Logged only. The donation is already saved,<br/>so the giver still sees the thank-you and a retry<br/>cannot become a second donation.\n                    end\n                end\n\n                SM-->>G: Redirect to /Stoet with a thank-you toast\n            end\n        end\n    end\n\n    ST->>IS: GET /Admin/Donations (Admin or Employee)\n    IS->>DB: SELECT the most recent donations\n    IS-->>ST: list - amount or items, name, email, greeting\n\n    Note over G,ST: An anonymous money donation sends no mail - there is nobody to write to.\n"}, {"id": "marsvin-sequence-chat", "group": "Sequence", "title": "Support chat (Pip)", "desc": "How the chat assistant answers.", "src": "sequenceDiagram\n    autonumber\n    actor V as Visitor\n    participant JS as chat.js\n    participant RL as RateLimiter (\"chat\")\n    participant CH as ChatModel (/Chat)\n    participant KA as KeywordChatAssistant\n    participant SK as ShopKnowledge\n    participant CA as ICatalog\n\n    Note over V,CA: The support chat \"Pip\". Not an AI service: a keyword lookup inside the app.<br/>Nothing leaves the server, nothing is stored, nothing costs money.\n\n    V->>JS: types a question, or clicks an example\n    JS->>CH: POST /Chat (message, lang, previous question, antiforgery token)\n    CH->>RL: 20 questions per minute per IP?\n    alt over the limit\n        RL-->>JS: 429\n        JS-->>V: \"wait a minute and try again\"\n    else within the limit\n        CH->>CH: antiforgery token valid?<br/>question 1-200 characters?\n        alt too long or empty\n            CH-->>JS: \"write a question of at most 200 characters\"\n        else ok\n            CH->>KA: Reply(question, english, previous)\n\n            alt contains an email address or 8+ digits in a row\n                KA-->>CH: \"please don't type personal details here\"\n                Note over KA: Checked first, before anything is looked up.\n            else about how the site is built or protected\n                KA-->>CH: \"that's not something I answer\"\n            else about orders, accounts, customers or staff\n                KA-->>CH: \"I can't see orders or accounts\"\n            else sounds like a sick animal\n                KA-->>CH: \"contact a vet\" - never a diagnosis\n            else something it can work out\n                KA->>CA: catalogue, opening hours, ShippingCalculator, food list\n                KA-->>CH: open now? / shipping for 3 kg / cage size for 4 /<br/>animals for sale / yes-or-no on a food\n            else a lookup\n                KA->>SK: Build(catalog)\n                SK->>CA: Animals, Accessories (public data only)\n                SK-->>KA: one fact per animal, product, food,<br/>FAQ entry, care-guide paragraph, delivery rule\n                KA->>KA: fold letters, synonyms, spelling correction,<br/>score by how rare each matching word is,<br/>require more than half the question covered\n                alt a fact matches\n                    KA-->>CH: answer worded for the question<br/>(advice first, price first, or a short list)\n                else nothing matches\n                    opt a follow-up (\"what does she cost?\")\n                        KA->>KA: try again with the subject<br/>of the previous question added\n                    end\n                    KA-->>CH: \"I don't know that\" + up to 3 questions it can answer\n                end\n            end\n\n            CH-->>JS: JSON { answer, suggestions }\n            JS->>JS: textContent, never innerHTML\n            JS-->>V: answer, and suggestion buttons if any\n        end\n    end\n\n    Note over KA,SK: The real boundary is what ShopKnowledge contains: no orders, accounts,<br/>customers or staff, and nothing about logins, the database or security.<br/>A refused previous question is thrown away, never used as context.\n"}, {"id": "marsvin-sequence-jwt-api", "group": "Sequence", "title": "JWT API", "desc": "Getting a token and using it on /api.", "src": "sequenceDiagram\n    autonumber\n    actor C as Client (signed in on the website)\n    participant T as POST /api/auth/token\n    participant J as JwtTokens\n    participant A as /api endpoint (JWT bearer)\n    participant DB as dbo.Users\n\n    Note over C,T: Step 1 - get a token. Needs the website login cookie,<br/>so the email link and authenticator code already happened.\n    C->>T: POST (login cookie)\n    T->>DB: FindById(user id from cookie)\n    DB-->>T: user (active?)\n    alt cookie missing, or account inactive\n        T-->>C: 302 to login / 401\n    else\n        T->>J: Create(user, key, now)\n        J-->>T: HS256 token: sub, name, email, role, stamp<br/>iss, aud, exp = now + 15 min\n        T-->>C: 200 { token, tokenType, expiresAt } - Cache-Control: no-store\n    end\n\n    Note over C,A: Step 2 - use it. The cookie is ignored on /api.\n    C->>A: GET /api/... Authorization: Bearer token\n    A->>A: signature, issuer, audience, expiry (30 s skew),<br/>algorithm pinned to HS256\n    alt bad, tampered, expired or \"alg: none\"\n        A-->>C: 401 (bare, no HTML error page)\n    else token accepted\n        A->>DB: FindById(sub)\n        DB-->>A: user\n        alt inactive, stamp changed (password), or role changed\n            A-->>C: 401 - token refused\n        else account unchanged\n            A->>A: role policy (Any user / Staff / Admin)\n            alt role not allowed\n                A-->>C: 403\n            else allowed\n                A-->>C: 200 JSON (own orders: user id from token only)\n            end\n        end\n    end\n"}, {"id": "marsvin-sequence-admin-edit", "group": "Sequence", "title": "Admin edit with audit log", "desc": "A staff change and its AuditLog entry.", "src": "sequenceDiagram\n    autonumber\n    actor A as Admin\n    participant AU as Authorization middleware\n    participant EM as Admin/Products/Edit\n    participant PH as PhotoUploadHelper\n    participant CA as ICatalogAdmin\n    participant AL as IAuditLogStore\n    participant DB as MarsvinDb\n\n    A->>AU: POST /Admin/Products/Edit/{id} (fields, optional photo)\n    AU->>AU: auth cookie present?<br/>[Authorize(Roles = \"Admin\")] satisfied?\n\n    alt not signed in\n        AU-->>A: Redirect to /Account/Login\n    else signed in, wrong role (Employee or Customer)\n        AU-->>A: Redirect to /Account/AccessDenied\n    else authorised\n        AU->>EM: handler runs\n        EM->>EM: validate ModelState + anti-forgery token<br/>(a typed photo address must point at an image under /img)\n\n        alt invalid\n            EM-->>A: Page() with errors\n        else valid\n            opt a photo was uploaded\n                EM->>PH: SaveAsync(file, \"products\")\n                Note over PH: Declared type must be JPEG, PNG, WebP or GIF,<br/>the file's own first bytes must match it,<br/>max 5 MB. Saved under a new random name.\n                PH-->>EM: url, or a validation error\n            end\n            alt id = 0 (new product)\n                EM->>CA: CreateStockProduct(product)\n                EM->>AL: Record(actorId, actorName, \"Product.Created\", name)\n            else existing product\n                EM->>CA: UpdateStockProduct(product)\n                EM->>AL: Record(actorId, actorName, \"Product.Updated\", name)\n            end\n            CA->>DB: INSERT / UPDATE dbo.Products + dbo.StockProducts\n            AL->>DB: INSERT dbo.AuditLog\n            Note over AL,DB: ActorName is a snapshot, not a FK -<br/>the entry survives the account being deleted.<br/>The app never updates or deletes AuditLog rows.\n            EM-->>A: Redirect to /Admin/Products\n        end\n    end\n\n    Note over AU,EM: All 16 pages under /Admin carry their own [Authorize].<br/>CRUD pages, Users, Export and AuditLog are Admin only,<br/>Stock, Orders, Messages, Donations, Shop, Schedule and the<br/>/Admin start page are open to Employee as well. Employee changes<br/>to stock, animal status and order status are audited too.<br/>The role in the cookie is re-read from the database on every request.\n"}, {"id": "marsvin-sequence-inactivity-cleanup", "group": "Sequence", "title": "GDPR inactivity cleanup", "desc": "Warning e-mails and automatic account deletion.", "src": "sequenceDiagram\n    autonumber\n    participant HS as InactiveAccountCleanupService\n    participant US as SqlUserAccountStore\n    participant DB as MarsvinDb\n    participant ES as IEmailSender\n    actor K as Kunde\n\n    Note over HS: BackgroundService started by the host.<br/>Runs once at startup, then every 24 hours.<br/>Implements the storage-limitation rule documented on /Privatliv.\n\n    loop every 24 hours\n        HS->>US: DeleteInactiveCustomers(now - 2 years)\n        US->>DB: Customer accounts with LastActiveAt before the cutoff\n        loop each account\n            US->>DB: DeleteUser in one transaction:<br/>PendingLogins, CartItems, Shifts and TimeOffRequests deleted,<br/>Orders.UserId set to NULL, Users row deleted\n        end\n        Note over HS,DB: Orders survive - UserId is nullable,<br/>so the sales history is kept without a person attached.<br/>Delete runs first, so nobody gets a warning<br/>on the same pass that removes them.\n\n        HS->>US: GetCustomersNeedingInactivityWarning(stage 2: 1 month left)\n        loop each account\n            HS->>ES: \"Din konto slettes om ca. en maaned\"<br/>or \"...will be deleted in about one month\"\n            alt mail sent\n                HS->>US: SetInactivityWarningStage(userId, 2)\n            else sending failed\n                Note over HS: Stage left unchanged, so it is retried<br/>on the next run and a warning that never<br/>arrived is not recorded as sent.\n            end\n        end\n\n        HS->>US: GetCustomersNeedingInactivityWarning(stage 1: 2 months left)\n        loop each account\n            HS->>ES: \"Din konto slettes om ca. to maaneder\"<br/>or \"...will be deleted in about two months\"\n            HS->>US: SetInactivityWarningStage(userId, 1)\n        end\n    end\n\n    K->>US: any successful login (ConfirmLogin or VerifyTotp)\n    US->>DB: RecordActivity: LastActiveAt = now, InactivityWarningStage = 0\n    Note over K,DB: Logging in once is all it takes to keep the account.\n\n    Note over HS,ES: No browser is involved, so each warning is written in<br/>Users.PrefersEnglish - the language the account last used.<br/>Only Customer accounts are in scope.<br/>Employee and Admin accounts are never auto-deleted.<br/>An exception in one run is logged, and the next run tries again.\n"}, {"id": "marsvin-activity-checkout", "group": "Activity and state", "title": "Activity: checkout", "desc": "Checkout as an activity diagram.", "src": "flowchart TB\n    subgraph KUNDE[\"Kunde or Gaest\"]\n        A1([\"Start: opens /Cart\"])\n        A2[\"Reviews cart and delivery info,<br/>goes to /Cart/Payment\"]\n        A2b[\"Step 1 - your details:<br/>guest: name + email; phone;<br/>private or company (+ CVR);<br/>'I am 16 or older' if a guinea pig is in the order\"]\n        A3[\"Step 2 - chooses Pickup or Shipping\"]\n        A4[\"Shipping: enters an address and picks<br/>PostNord, GLS or DAO - each shown with price,<br/>destination, expected delivery, weight, parcels\"]\n        A5[\"Step 3 - chooses Card or MobilePay\"]\n        A6[\"Card: fills in the demo card form<br/>(or one click: demo card)\"]\n        A9([\"End: confirmation page + email\"])\n        A10([\"End: errors marked on the form,<br/>or back to the cart with a message\"])\n    end\n\n    subgraph SYSTEM[\"marsvin-web\"]\n        B1{\"Staff account<br/>(Employee / Admin)?\"}\n        B2[\"Redirect away -<br/>staff accounts cannot buy\"]\n        B2b[\"Shipping offered only if the cart<br/>has at least one non-animal line.<br/>Prices shown come from ShippingCalculator\"]\n        B3[\"PaymentModel validates only what applies:<br/>guest name + email, phone if Shipping,<br/>address if Shipping, age box if an animal,<br/>company name + CVR check digit,<br/>card digits if Card\"]\n        B4{\"Valid?\"}\n        B5[\"Open transaction<br/>load the cart lines<br/>(database cart, or the guest's session lines)\"]\n        B6{\"Cart empty?\"}\n        B7{\"Shipping but<br/>only animals?\"}\n        B8{\"Shipping without<br/>an address?\"}\n        B9[\"ValidateLine per line<br/>(UPDLOCK, HOLDLOCK):<br/>animal Available and 4+ weeks old,<br/>stock sufficient\"]\n        B10{\"All lines OK?\"}\n        B10b[\"Price the shipment here, from the weights<br/>just read: parcels of max 20 kg,<br/>rate per carrier, free from 2,000 kr.<br/>Nothing posted by the form is used\"]\n        B11[\"INSERT Orders + OrderItems<br/>Status = Placed, total = items + shipping,<br/>cost / weight / parcels stored as snapshots\"]\n        B12[\"ApplyStockChange:<br/>animal to Sold,<br/>stock decremented\"]\n        B13[\"Clear the cart, Commit\"]\n        B13b[\"Guest: stamp the order id into<br/>this browser's own session\"]\n        B14[\"Send confirmation email<br/>in the language the site was in\"]\n        B15[\"Rollback\"]\n        B16[\"Confirmation page: status steps,<br/>delivery and contact details,<br/>pickup note if an animal is in a shipped order\"]\n    end\n\n    subgraph DB[\"MarsvinDb\"]\n        C1[(\"Products / Animals /<br/>StockProducts\")]\n        C2[(\"Orders / OrderItems\")]\n    end\n\n    A1 --> B1\n    B1 -->|yes| B2\n    B1 -->|no - guest or Customer| A2\n    A2 --> B2b\n    B2b --> A2b\n    A2b --> A3\n    A3 -->|Shipping| A4\n    A3 -->|Pickup| A5\n    A4 --> A5\n    A5 -->|Card| A6\n    A5 -->|MobilePay: no card fields| B3\n    A6 --> B3\n    B3 --> B4\n    B4 -->|no| A10\n    B4 -->|yes| B5\n    B5 --> C1\n    B5 --> B6\n    B6 -->|yes| B15\n    B6 -->|no| B7\n    B7 -->|yes| B15\n    B7 -->|no| B8\n    B8 -->|yes| B15\n    B8 -->|no| B9\n    B9 --> B10\n    B10 -->|no| B15\n    B10 -->|yes| B10b\n    B10b --> B11\n    B11 --> C2\n    B11 --> B12\n    B12 --> C1\n    B12 --> B13\n    B13 --> B13b\n    B13b --> B14\n    B14 --> B16\n    B16 --> A9\n    B15 --> A10\n"}, {"id": "marsvin-activity-email-language", "group": "Activity and state", "title": "Activity: e-mail language", "desc": "Which language an e-mail is written in.", "src": "flowchart TB\n    START([\"An email is about to be sent\"])\n\n    subgraph BROWSER[\"In the browser\"]\n        TOGGLE[\"EN / DA toggle (lang-toggle.js)<br/>choice kept in localStorage\"]\n        COOKIE[\"marsvin-lang cookie<br/>'da' or 'en', path /, one year, SameSite=Lax<br/>written on every page load\"]\n        TOGGLE --> COOKIE\n    end\n\n    subgraph READ[\"SiteLanguage.Read - the only place the cookie is read\"]\n        CHECK{\"cookie value?\"}\n        EN[\"English\"]\n        DA[\"Danish\"]\n        NONE[\"not set<br/>(missing, or any other value)\"]\n        CHECK -->|\"exactly 'en'\"| EN\n        CHECK -->|\"exactly 'da'\"| DA\n        CHECK -->|\"anything else\"| NONE\n    end\n\n    COOKIE -.->|\"sent with every request\"| CHECK\n\n    WHO{\"Who caused the mail?\"}\n    START --> WHO\n\n    SELF[\"The recipient, in their own browser:<br/>login link, new account, password reset,<br/>password or email changed, order confirmation,<br/>donation thank-you, cancelling their own order\"]\n    STAFF[\"Staff, about an order:<br/>status changed on /Admin/Orders\"]\n    OTHER[\"Someone else, about an account:<br/>shift added or removed, day-off request<br/>to the admins, failed-login warning\"]\n    JOB[\"Nobody: the daily inactivity job\"]\n\n    WHO --> SELF\n    WHO --> STAFF\n    WHO --> OTHER\n    WHO --> JOB\n\n    USECOOKIE[\"Language of this request<br/>PageModel.IsEnglish()\"]\n    USEORDER[\"Orders.PlacedInEnglish<br/>saved at checkout\"]\n    USEUSER[\"Users.PrefersEnglish<br/>of the recipient\"]\n\n    SELF --> USECOOKIE\n    STAFF --> USEORDER\n    OTHER --> USEUSER\n    JOB --> USEUSER\n\n    EN -.-> USECOOKIE\n    DA -.-> USECOOKIE\n    NONE -.->|\"counts as Danish\"| USECOOKIE\n\n    SAVEORDER[\"Checkout stores the request's language<br/>on the order\"]\n    SAVEUSER[\"Every signed-in request<br/>(AuthCookiePrincipal.RevalidateAsync):<br/>copy the cookie to the account,<br/>only when it is 'da' or 'en' AND differs.<br/>Registration sets it for a new account\"]\n\n    USECOOKIE -.-> SAVEORDER\n    SAVEORDER -.-> USEORDER\n    CHECK -.-> SAVEUSER\n    SAVEUSER -.-> USEUSER\n\n    SEND[\"IEmailSender.SendAsync(to, subject, body, english)<br/>subject and body already written in that language;<br/>the flag only picks the footer the sender adds\"]\n    USECOOKIE --> SEND\n    USEORDER --> SEND\n    USEUSER --> SEND\n\n    SEND --> DONE([\"Mail in Danish or English, footer included\"])\n\n    NOTE[\"The cookie is never echoed anywhere - it is compared against two<br/>fixed values, so a tampered value cannot inject text into a mail or a page.<br/>Product names in an order mail stay as the order recorded them (Danish).<br/>Accounts and orders from before this existed count as Danish.\"]\n    SEND --- NOTE\n"}, {"id": "marsvin-state-animal", "group": "Activity and state", "title": "State: animal", "desc": "Available, reserved, sold, not for sale.", "src": "stateDiagram-v2\n    [*] --> Available : created by Admin<br/>(Admin/Animals/Edit - status is a form field)\n    [*] --> NotForSale : created by Admin<br/>(Admin/Animals/Edit - status is a form field)\n\n    NotForSale --> Available : staff sets status\n    Available --> NotForSale : withdrawn\n\n    Available --> Reserved : set by staff only<br/>(Admin/Stock, Animals/Edit)\n    Reserved --> Available : staff releases\n    Reserved --> Sold : set by staff only\n\n    Available --> Sold : checkout commits<br/>(SqlOrderStore.ApplyStockChange)\n    Sold --> Available : buyer cancels the order<br/>while it is still Placed<br/>(SqlOrderStore.Cancel)\n\n    Sold --> [*]\n\n    note right of Available\n        Added to the cart only if\n        Status = Available AND the\n        animal is at least 4 weeks old.\n        ValidateLine repeats both checks\n        inside the checkout transaction\n        (WITH UPDLOCK, HOLDLOCK).\n        An order with an animal also needs\n        the buyer's \"I am 16 or older\".\n    end note\n\n    note right of Reserved\n        As built, nothing sets Reserved\n        automatically - checkout goes\n        straight from Available to Sold.\n        Staff changes are written to\n        AuditLog (Animal.StatusChanged).\n    end note\n\n    note left of Sold\n        A bonded animal and its partner\n        are added to the cart together,\n        so both reach Sold in one order -\n        and both go back to Available\n        if that order is cancelled.\n        An animal is never shipped:\n        it is picked up in the shop.\n    end note\n"}, {"id": "marsvin-state-order", "group": "Activity and state", "title": "State: order", "desc": "Placed, processing, sent, delivered, cancelled.", "src": "stateDiagram-v2\n    [*] --> Placed : SqlOrderStore.Checkout commits<br/>(Status = 0)\n\n    Placed --> Processing : staff, on /Admin/Orders\n    Processing --> Sent : staff - optionally with a tracking number\n    Sent --> Completed : staff\n\n    Placed --> Cancelled : the buyer (receipt or order history),<br/>or staff\n    Processing --> Cancelled : staff only\n\n    Completed --> [*]\n    Cancelled --> [*]\n\n    note right of Placed\n        dbo.Orders.Status, a TINYINT:\n        0 Placed, 1 Processing, 2 Sent,\n        3 Completed, 4 Cancelled.\n        The buyer is emailed at every change,\n        in the language the order was placed in\n        (Data/OrderEmails.cs) and sees the\n        status on the receipt and under\n        Min konto.\n    end note\n\n    note right of Sent\n        The wording follows the delivery:\n        \"Sent\" for a shipped order,\n        \"Ready for pickup\" for a pickup.\n        Completed reads \"Delivered\" or\n        \"Picked up\" the same way.\n    end note\n\n    note left of Processing\n        Staff set the status from a list on\n        /Admin/Orders (Admin and Employee),\n        so they can also correct a mistake\n        by setting an earlier one, and may\n        cancel until the order has been sent.\n        Every change is written to AuditLog.\n    end note\n\n    note left of Cancelled\n        Cancelled is the highest number on\n        purpose: \"may still be cancelled\" is\n        the test Status <= latest (Placed for\n        the buyer, Processing for staff), in\n        the same UPDATE that cancels - a\n        second click finds nothing to cancel.\n        In that transaction the items go back:\n        stock is added back, animals return\n        from Sold to Available.\n        Cancelled is final: UpdateStatus\n        refuses to move a cancelled order.\n    end note\n"}, {"id": "marsvin-ssd-place-order", "group": "Course models", "title": "System sequence diagram", "desc": "SSD for “place order”.", "src": "sequenceDiagram\n    autonumber\n    actor K as Kunde or Gaest\n    participant S as \":Marsvin webshop\"\n\n    Note over K,S: System Sequence Diagram - the system is one black box.<br/>No account is needed: a guest gives a name and an email.\n\n    K->>S: viewCart()\n    S-->>K: lines, line totals, cart total,<br/>cheapest shipping and amount left to free shipping\n\n    K->>S: goToPayment()\n    S-->>K: details form, delivery options (shipping only if something is shippable),<br/>each carrier with price, destination, expected delivery, weight and parcels,<br/>payment methods, order summary\n\n    K->>S: submitPayment(name and email if guest, phone, buyerType, company and CVR,<br/>ageConfirmed, deliveryMethod, address, carrier,<br/>paymentMethod, cardDetails if Card)\n\n    alt cart empty\n        S-->>K: error(\"Din kurv er tom\")\n    else form invalid (name, email, phone, address, CVR, age box, card number, expiry, CVC)\n        S-->>K: validation errors marked on the payment page\n    else shipping chosen but the order is only animals\n        S-->>K: error(\"Vaelg afhentning\")\n    else an item is unavailable, too young or out of stock\n        S-->>K: error(naming the item), back to the cart\n    else accepted\n        S-->>K: orderConfirmation(orderId, status Placed, total incl. shipping,<br/>delivery, expected delivery, payment method)\n        S-->>K: confirmation email, in the language of the site\n    end\n\n    opt later, while the order is still Placed (staff can cancel until it is sent)\n        K->>S: cancelOrder(orderId)\n        S-->>K: order Cancelled, items back in stock, email\n    end\n\n    opt as staff move the order along\n        S-->>K: email: Processing, Sent (with tracking number) or ready for pickup, Completed\n    end\n"}, {"id": "marsvin-communication-checkout", "group": "Course models", "title": "Communication diagram", "desc": "Checkout as a communication diagram.", "src": "flowchart LR\n    K([\"Kunde or Gaest\"])\n    PM[\"PaymentModel\"]\n    CS[\"ICartStore<br/>SqlCartStore or SessionCartStore\"]\n    OS[\"SqlOrderStore\"]\n    SC[\"ShippingCalculator\"]\n    SE[\"Session\"]\n    ES[\"IEmailSender\"]\n    CM[\"ConfirmationModel\"]\n    DB[(\"MarsvinDb\")]\n\n    K -->|\"1: POST /Cart/Payment\"| PM\n    PM -->|\"2: GetLines(userId)\"| CS\n    CS -->|\"2.1: SELECT CartItems JOIN Products<br/>(guest: session lines, prices read live)\"| DB\n    PM -->|\"3: Checkout(userId or null, delivery, address,<br/>carrier, paymentMethod, guest name/email,<br/>guest lines, phone, age, company, language)\"| OS\n    OS -->|\"3.1: load cart lines\"| DB\n    OS -->|\"3.2: ValidateLine per line\"| DB\n    OS -->|\"3.3: Quote(carrier, weight, date, itemsTotal)\"| SC\n    OS -->|\"3.4: INSERT Orders + OrderItems<br/>with shipping snapshots\"| DB\n    OS -->|\"3.5: ApplyStockChange\"| DB\n    OS -->|\"3.6: ClearCart, Commit\"| DB\n    PM -->|\"4: Clear(cart)\"| CS\n    PM -->|\"5: guest only - SetInt32('GuestOrderId', orderId)\"| SE\n    PM -->|\"6: SendAsync(confirmation)\"| ES\n    PM -->|\"7: Redirect Confirmation/{orderId}\"| K\n    K -->|\"8: GET /Cart/Confirmation/{orderId}\"| CM\n    CM -->|\"9: Customer - FindForUser(orderId, userId)<br/>guest - FindById only if the session holds this id\"| OS\n"}];
